  "prediction_basis_card_ids": [
    "C22", "C01", "C16", "C17", "C29", "C41", "C54",
    "C07", "C37", "C44", "C26", "C18", "C30", "C40", "C46",
    "C53", "C34", "C28", "C14", "C38", "C48",
    "C02", "C10", "C23", "C24"
  ],
  "claims": [
    {
      "claim": "Structurally related tetrabenazine, a rigid methoxy-substituted basic ketone alkaloid, has measured absolute oral bioavailability of 0.1–8.5% across fasted and fed patients, well below the 20% threshold.",
      "card_ids": ["C22", "C01", "C16", "C17", "C29", "C41", "C54"]
    },
    {
      "claim": "Phenol-containing basic amines meptazinol and pentazocine have mean absolute oral bioavailability of about 9% and 18%, respectively, below the 20% threshold; the query shares a phenol and basic N-methyl piperidine motif.",
      "card_ids": ["C07", "C37", "C44", "C26", "C18", "C30", "C40", "C46"]
    },
    {
      "claim": "Methoxyphenol/fused-ring analogs 2-methoxyestradiol and estradiol show oral bioavailability of about 1–5%, indicating extensive first-pass metabolism for this phenolic/methoxy scaffold.",
      "card_ids": ["C53", "C34", "C28", "C14", "C38", "C48"]
    },
    {
      "claim": "Smaller methoxyaryl ketone/lactam compounds apocynin and aniracetam also show <10% or extremely low oral bioavailability, consistent with low F for the query's methoxyaryl ketone/enol ether system.",
      "card_ids": ["C02", "C10"]
    },
    {
      "claim": "The only high-F records (ethinyl estradiol 51%, drospirenone 76–85%) concern structurally distinct steroids lacking the query's basic amine, ketone, and enol ether, so they do not transfer to the query.",
      "card_ids": ["C21", "C47"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "current_gold_voting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "changed",
      "card_ids": [
        "C22", "C01", "C16", "C17", "C29", "C41", "C54",
        "C07", "C37", "C44", "C26", "C18", "C30", "C40", "C46",
        "C53", "C34", "C28", "C14", "C38", "C48",
        "C02", "C10", "C23", "C24"
      ]
    }
  ],
  "evidence_gaps": [
    "No direct measured oral bioavailability for the query molecule itself.",
    "Transfer from tetrabenazine, meptazinol, pentazocine, and steroid analogs is structural/inferential rather than an exact matched-condition measurement.",
    "The specific first-pass liability of the enol ether/ketone and phenol motifs in the query is not directly quantified.",
    "High-F comparator records (ethinyl estradiol, drospirenone) are not structurally applicable to the query."
  ],
  "decision_summary": "Multiple transferable L1 records show low absolute oral bioavailability for structurally related methoxyaryl, phenolic, basic-amine, and ketone-containing alkaloids (tetrabenazine 0.1–8.5%, meptazinol ~9%, pentazocine ~18%, 2-methoxyestradiol 1–2%, estradiol ~5%, apocynin <10%). The query's phenol, basic N-methyl piperidine, ketone, and enol ether motifs align with these low-F scaffolds, and the high-F comparators are not structurally applicable. Therefore F >= 20% is not supported; prediction is low with moderate confidence."
}

